194:     let base = [pos2(0.0, 0.0), pos2(1.0, 0.0), pos2(1.0, 1.0), pos2(0.0, 1.0)];
195:     let k = rot.rem_euclid(4) as usize;
196:     let mut u = [base[0], base[0], base[0], base[0]];
