288:     pub fn photos_cmd(&mut self, c: &str) {
289:         let tgt = self.photos_target();
290:         let (name, arg) = c.split_once(':').unwrap_or((c, ""));
291:         match name {
292:             "fit" => {
293:                 self.shell.photos.zoom = 1.0;
294:                 self.shell.photos.pan = Vec2::ZERO;
295:             }
296:             "actual" => {
297:                 if let Some(l) = &self.shell.photos.cur {
298:                     let z = (l.w.max(l.h) as f32 / 700.0).clamp(1.0, 6.0);
299:                     self.shell.photos.zoom = z;
300:                 }
301:             }
302:             "zoomin" => self.shell.photos.zoom = (self.shell.photos.zoom * 1.4).min(10.0),
303:             "zoomout" => self.shell.photos.zoom = (self.shell.photos.zoom / 1.4).max(0.4),
304:             "rotl" => self.shell.photos.rot -= 1,
305:             "rotr" => self.shell.photos.rot += 1,
306:             "fliph" => self.shell.photos.flip_h = !self.shell.photos.flip_h,
307:             "flipv" => self.shell.photos.flip_v = !self.shell.photos.flip_v,
308:             "slideshow" => {
309:                 if self.shell.photos.open.is_none() {
310:                     let first = self.photos_list().first().cloned();
311:                     if let Some(e) = first {
312:                         self.photos_show(e.loc);
313:                     }
314:                 }
315:                 self.shell.photos.slideshow = !self.shell.photos.slideshow;
316:                 self.shell.photos.slide_t = self.time;
317:             }
318:             "slide_from" => {
319:                 if let Some(l) = tgt.clone() {
320:                     self.photos_show(l);
321:                     self.shell.photos.slideshow = true;
322:                     self.shell.photos.slide_t = self.time;
323:                 }
324:             }
325:             "view" => {
326:                 if let Some(l) = tgt.clone() {
327:                     self.photos_show(l);
328:                 }
329:             }
330:             "view_idx" => {
331:                 if let Some(e) = arg.parse::<usize>().ok().and_then(|i| self.shell.photos.all.get(i).cloned()) {
332:                     self.photos_show(e.loc);
333:                 }
334:             }
335:             "album" => {
336:                 let ph = &mut self.shell.photos;
337:                 ph.open = None;
338:                 ph.album = match arg {
339:                     "all" => Album::All,
340:                     "fav" => Album::Favorites,
341:                     n => n.parse::<usize>().ok().and_then(|i| ph.folders.get(i).map(|f| Album::Folder(f.0.clone()))).unwrap_or(Album::All),
342:                 };
343:             }
344:             "fav" => {
345:                 if let Some(l) = tgt.clone() {
346:                     self.photos_toggle_fav(l);
347:                 }
348:             }
349:             "info" => {
350:                 self.shell.photos.info = !self.shell.photos.info;
351:                 if self.shell.photos.info {
352:                     self.shell.photos.edit = false;
353:                 }
354:             }
355:             "edit" => {
356:                 if self.shell.photos.open.is_none() {
357:                     if let Some(l) = tgt.clone() {
358:                         self.photos_show(l);
359:                     }
360:                 }
361:                 self.shell.photos.edit = !self.shell.photos.edit;
362:                 if self.shell.photos.edit {
363:                     self.shell.photos.info = false;
364:                 }
365:             }
366:             "back" => {
367:                 let ph = &mut self.shell.photos;
368:                 ph.open = None;
369:                 ph.slideshow = false;
370:                 ph.edit = false;
371:                 ph.info = false;
372:             }
373:             "reveal" => {
374:                 if let Some(l) = tgt.and_then(|l| l.parent()) {
375:                     self.acts.push(Act::OpenApp(crate::shell::AppId::Files));
376:                     self.acts.push(Act::Nav(Route::Loc(l)));
377:                 }
378:             }
379:             "wallpaper" => {
380:                 if let Some(l) = tgt {
381:                     self.acts.push(Act::WallpaperFrom(l));
382:                 }
383:             }
384:             "sort" => self.shell.photos.sort = arg.parse().unwrap_or(0),
385:             "tile" => self.shell.photos.tile = arg.parse().unwrap_or(210.0),
386:             "captions" => self.shell.photos.captions = !self.shell.photos.captions,
387:             "fill" => self.shell.photos.fill = !self.shell.photos.fill,
388:             "search" => {
389:                 self.shell.photos.search_open = true;
390:                 self.shell.photos.search_focus = true;
391:             }
392:             "refresh" => {
393:                 self.shell.photos.scanned = false;
394:                 self.toast("Library refreshed", true);
395:             }
396:             "save" => self.photos_save(),
397:             _ => {}
398:         }
399:         self.shell.photos.ctx = None;
400:     }
