402:     pub fn photos_list(&self) -> Vec<Entry> {
403:         let ph = &self.shell.photos;
404:         let q = ph.search.trim().to_lowercase();
405:         let mut v: Vec<Entry> = ph
406:             .all
407:             .iter()
408:             .filter(|e| match &ph.album {
409:                 Album::All => true,
410:                 Album::Favorites => ph.favs.contains(&e.loc),
411:                 Album::Folder(f) => e.loc.parent().as_ref() == Some(f),
412:             })
413:             .filter(|e| q.is_empty() || e.name.to_lowercase().contains(&q))
414:             .cloned()
415:             .collect();
416:         match ph.sort {
417:             0 => {}
418:             1 => v.reverse(),
419:             2 => v.sort_by(|a, b| natural_cmp(&a.name, &b.name)),
420:             _ => v.sort_by(|a, b| b.size.cmp(&a.size)),
421:         }
422:         v
423:     }
