425:     fn photos_save(&mut self) {
426:         let Some(cur) = &self.shell.photos.cur else { return };
427:         let ph = &self.shell.photos;
428:         let data = process(&cur.rgba, cur.w, cur.h, &ph.adj);
429:         let mut img = image::RgbaImage::from_raw(cur.w as u32, cur.h as u32, data).unwrap();
430:         for _ in 0..ph.rot.rem_euclid(4) {
431:             img = image::imageops::rotate90(&img);
432:         }
433:         if ph.flip_h {
434:             img = image::imageops::flip_horizontal(&img);
435:         }
436:         if ph.flip_v {
437:             img = image::imageops::flip_vertical(&img);
438:         }
439:         let rgb = image::DynamicImage::ImageRgba8(img).to_rgb8();
440:         let mut bytes = vec![];
441:         if image::codecs::jpeg::JpegEncoder::new_with_quality(&mut bytes, 92).encode_image(&rgb).is_err() {
442:             self.toast("Could not encode the image", false);
443:             return;
444:         }
445:         let Some(dir) = cur.loc.parent() else { return };
446:         let stem = cur.loc.name();
447:         let stem = stem.rsplit_once('.').map(|x| x.0.to_string()).unwrap_or(stem);
448:         let mut name = format!("{stem} edited.jpg");
449:         let mut n = 2;
450:         while self.be.stat(&dir.join(&name)).is_ok() {
451:             name = format!("{stem} edited {n}.jpg");
452:             n += 1;
453:         }
454:         let dest = dir.join(&name);
455:         let res = self.be.create_file(&dir, &name).and_then(|_| self.be.registry.get(&dest.fs).ok_or("unavailable".to_string())?.write(&dest.path, &bytes).map_err(|e| e.to_string()));
456:         match res {
457:             Ok(()) => {
458:                 self.toast(format!("Saved \u{201c}{name}\u{201d}"), true);
459:                 self.acts.push(Act::Refresh);
460:                 self.shell.photos.scanned = false;
461:             }
462:             Err(e) => self.toast(format!("Save failed: {e}"), false),
463:         }
464:     }
