487:     fn photos_load_cur(&mut self, ctx: &egui::Context) {
488:         let Some(l) = self.shell.photos.open.clone() else { return };
489:         if self.shell.photos.cur.as_ref().is_some_and(|c| c.loc == l) {
490:             return;
491:         }
492:         let prev = self.shell.photos.cur.as_ref().map(|c| c.tex.clone());
493:         let bytes = self.be.read_bytes(&l, 48 * 1024 * 1024);
494:         let size = bytes.as_ref().map(|b| b.len() as u64).unwrap_or(0);
495:         let Some(img) = bytes.ok().and_then(|b| image::load_from_memory(&b).ok()) else {
496:             self.toast("Could not open that image", false);
497:             self.shell.photos.open = None;
498:             return;
499:         };
500:         let img = if img.width().max(img.height()) > 1600 { img.resize(1600, 1600, image::imageops::FilterType::Triangle) } else { img };
501:         let rgba = img.to_rgba8();
502:         let (w, h) = (rgba.width() as usize, rgba.height() as usize);
503:         let mk = |data: &[u8], w: usize, h: usize, name: &str| ctx.load_texture(name.to_string(), egui::ColorImage::from_rgba_unmultiplied([w, h], data), TextureOptions::LINEAR);
504:         let orig = mk(rgba.as_raw(), w, h, &format!("ph-o-{}", l.path));
505:         let mut hist = [0f32; 48];
506:         for px in rgba.as_raw().chunks_exact(4).step_by(3) {
507:             let lum = (0.2126 * px[0] as f32 + 0.7152 * px[1] as f32 + 0.0722 * px[2] as f32) / 255.0;
508:             hist[((lum * 47.0) as usize).min(47)] += 1.0;
509:         }
510:         let mx = hist.iter().cloned().fold(1.0, f32::max);
511:         for v in hist.iter_mut() {
512:             *v /= mx;
513:         }
514:         // tiny preview of every preset
515:         let small = image::imageops::thumbnail(&rgba, 120, 120);
516:         let (sw, sh) = (small.width() as usize, small.height() as usize);
517:         let presets = PRESETS.iter().enumerate().map(|(i, (_, a))| mk(&process(small.as_raw(), sw, sh, a), sw, sh, &format!("ph-p{i}-{}", l.path))).collect();
518:         let adj = self.shell.photos.adj;
519:         let tex = if adj == Adjust::default() { orig.clone() } else { mk(&process(rgba.as_raw(), w, h, &adj), w, h, &format!("ph-e-{}", l.path)) };
520:         self.shell.photos.cur = Some(Loaded { loc: l, rgba: rgba.into_raw(), w, h, tex, orig, hist, presets, bytes: size });
521:         if let Some(p) = prev {
522:             self.shell.photos.prev = Some((p, self.time));
523:         }
524:     }
