610:     pub fn draw_photos(&mut self, ui: &mut Ui, fr: &Frame) {
611:         let ctx = ui.ctx().clone();
612:         if !self.shell.photos.scanned {
613:             self.photos_scan();
614:         }
615:         let list = self.photos_list();
616:         let mut folders: Vec<(Location, usize)> = vec![];
617:         for e in &self.shell.photos.all {
618:             if let Some(par) = e.loc.parent() {
619:                 match folders.iter_mut().find(|f| f.0 == par) {
620:                     Some(f) => f.1 += 1,
621:                     None => folders.push((par, 1)),
622:                 }
623:             }
624:         }
625:         folders.sort_by(|a, b| b.1.cmp(&a.1));
626:         self.shell.photos.folders = folders.clone();
627:         let viewer = self.shell.photos.open.is_some();
628:         let vs = spring_to(&ctx, "ph-viewer", if viewer { 1.0 } else { 0.0 }, 200.0, 26.0).clamp(0.0, 1.0);
629:         self.photos_sidebar(ui, fr, &folders);
630:         self.photos_grid(ui, fr, &list, viewer);
631:         if vs > 0.01 {
632:             self.photos_load_cur(&ctx);
633:             if self.shell.photos.dirty {
634:                 self.photos_reprocess(&ctx);
635:             }
636:             self.draw_photo_viewer(ui, fr, vs, &list);
637:         }
638:         self.photos_toolbar(ui, fr, &list, vs);
639:     }
