641:     fn photos_sidebar(&mut self, ui: &mut Ui, fr: &Frame, folders: &[(Location, usize)]) {
642:         if fr.side.width() < 24.0 {
643:             return;
644:         }
645:         let th = self.th.clone();
646:         let saved = ui.clip_rect();
647:         ui.set_clip_rect(fr.side.intersect(saved));
648:         let p = ui.painter().clone();
649:         let left = fr.win.left();
650:         let gear = Rect::from_center_size(pos2(left + SIDEBAR_W - 28.0, fr.win.top() + APPBAR_H / 2.0), vec2(30.0, 30.0));
651:         if self.icon_button(ui, gear, "settings-minimalistic", "ph-gear", Btn::Quiet, true).on_hover_text("Photos settings  Ctrl+,").clicked() {
652:             self.shell.settings = Some((crate::shell::AppId::Photos, 0));
653:         }
654:         // identity row
655:         let ws = Rect::from_min_size(pos2(left + 12.0, fr.win.top() + 54.0), vec2(SIDEBAR_W - 24.0, 42.0));
656:         let av = Rect::from_min_size(ws.min + vec2(7.0, 7.0), vec2(28.0, 28.0));
657:         shadow(&p, av, 9.0, 2.0, 6.0, -1.0, c(255, 122, 89, 0.45));
658:         grad_fill(&p, av, 9.0, hex("#ff9fb8"), hex("#ff7a59"));
659:         rim(&p, av, 9.0, 1.0, Color32::from_white_alpha(130), true, 14.0);
660:         self.ico(&p, "gallery", Ic::Duo, av.center(), 16.0, Color32::WHITE);
661:         p.text(pos2(av.right() + 9.0, ws.center().y - 7.5), Align2::LEFT_CENTER, "Photos", f_semi(13.0), th.ink1);
662:         p.text(pos2(av.right() + 9.0, ws.center().y + 8.0), Align2::LEFT_CENTER, format!("{} in library", self.shell.photos.all.len()), f_medium(11.0), th.ink3);
663:         // storage card
664:         let total: u64 = self.shell.photos.all.iter().map(|e| e.size).sum();
665:         let card = Rect::from_min_size(pos2(left + 12.0, fr.side.bottom() - 14.0 - 62.0), vec2(SIDEBAR_W - 24.0, 62.0));
666:         elevate(&p, &th, card, 14.0, 2);
667:         grad_fill(&p, card, 14.0, th.card_top, th.card_bottom);
668:         rim(&p, card, 14.0, 1.2, th.rim, true, 30.0);
669:         p.text(card.left_top() + vec2(14.0, 18.0), Align2::LEFT_CENTER, "Library size", f_semi(T_META), th.ink1);
670:         p.text(card.right_top() + vec2(-14.0, 18.0), Align2::RIGHT_CENTER, format_size(total), f_semi(T_META), th.ink2);
671:         let bar = Rect::from_min_size(card.left_top() + vec2(14.0, 32.0), vec2(card.width() - 28.0, 8.0));
