978:         // opaque, theme-aware backing so the library never shows through the viewer
979:         {
980:             let back = if th.dark { hex("#141b29") } else { hex("#f3f6fb") };
981:             let rr = R_WIN as u8;
982:             let round = egui::CornerRadius { nw: 0, ne: 0, sw: if fr.has_side() { 0 } else { rr }, se: rr };
