368:             if e.symlink {
369:                 continue;
370:             }
371:             if e.is_dir {
372:                 if self.skip.iter().any(|s| *s == e.loc.path) {
373:                     continue;
374:                 }
375:                 let idx = self.nodes.len();
376:                 let mut node = DirNode { name: e.name.clone(), path: e.loc.path.clone(), parent: Some(i), size: 0, own: 0, files: 0, children: vec![], top_files: vec![], newest: e.modified.unwrap_or(0), junk: None, in_junk, done: false };
