415:     fn classify_file(&self, e: &Entry, siblings: &HashSet<String>, in_downloads: bool) -> Option<Junk> {
416:         let name = e.name.as_str();
417:         let ext = lower_ext(name);
418:         let size = e.size;
419:         let age_days = e.modified.map(|m| ((self.now - m) / DAY).max(0));
420:         let mk = |kind, safety, reason: String, restore| Some(Junk { path: e.loc.path.clone(), name: e.name.clone(), is_dir: false, kind, safety, reason, restore, modified: e.modified, size, node: None });
421:         // temporary leftovers
422:         let temp_ext = matches!(ext.as_str(), "tmp" | "temp" | "bak" | "swp" | "swo" | "crdownload" | "part" | "partial" | "orig" | "dmp");
423:         let temp_name = name.ends_with('~') || matches!(name, ".DS_Store" | "Thumbs.db" | "desktop.ini") || (name.starts_with("core.") && name[5..].bytes().all(|b| b.is_ascii_digit()) && name.len() > 5);
424:         if (temp_ext || temp_name) && size >= 64 * 1024 {
425:             return mk(JunkKind::Temp, Safety::Safe, if ext == "crdownload" || ext == "part" || ext == "partial" { "Unfinished download".into() } else { "Temporary or backup leftover".into() }, None);
426:         }
427:         if (ext == "log" || name.contains(".log.")) && size >= 5 * 1024 * 1024 {
428:             return mk(JunkKind::Logs, Safety::Safe, format!("Log file of {}", crate::model::format_size(size)), None);
429:         }
430:         if in_downloads && matches!(ext.as_str(), "iso" | "dmg" | "pkg" | "exe" | "msi" | "deb" | "rpm" | "apk") && size >= 1024 * 1024 && age_days.map(|d| d >= 14).unwrap_or(false) {
431:             return mk(JunkKind::Installers, Safety::Review, format!("Installer in Downloads, untouched for {} days", age_days.unwrap_or(0)), None);
432:         }
433:         if size >= 100 * 1024 {
434:             if let Some(orig) = copy_original(name) {
435:                 if siblings.contains(&orig) {
436:                     return mk(JunkKind::Duplicates, Safety::Review, format!("Looks like a copy of \u{201c}{orig}\u{201d} in the same folder"), None);
437:                 }
438:             }
439:         }
440:         if let Some(d) = age_days {
441:             let archive = e.kind == Kind::Archive;
442:             if (size >= 200 * 1_000_000 && d >= 365) || (size >= 1_000_000_000 && d >= 120) || (archive && size >= 100 * 1_000_000 && d >= 180) {
443:                 let months = (d / 30).max(1);
444:                 return mk(JunkKind::LargeStale, Safety::Careful, format!("{} untouched for {} month{}", if archive { "Old archive" } else { "Large file" }, months, if months == 1 { "" } else { "s" }), None);
445:             }
446:         }
447:         None
448:     }
