548: /// Squarified treemap (Bruls et al.). Pure geometry so it can be tested: `sizes` must be sorted descending.
549: pub fn squarify(sizes: &[f64], x: f64, y: f64, w: f64, h: f64) -> Vec<(f64, f64, f64, f64)> {
550:     let mut out = vec![(0.0, 0.0, 0.0, 0.0); sizes.len()];
551:     let total: f64 = sizes.iter().sum();
552:     if sizes.is_empty() || total <= 0.0 || w <= 0.0 || h <= 0.0 {
553:         return out;
554:     }
555:     let scale = w * h / total;
556:     let areas: Vec<f64> = sizes.iter().map(|s| s * scale).collect();
557:     let (mut x, mut y, mut w, mut h) = (x, y, w, h);
558:     let mut i = 0;
559:     while i < areas.len() {
560:         let short = w.min(h);
561:         let worst = |row: &[f64]| -> f64 {
562:             let s: f64 = row.iter().sum();
563:             if s <= 0.0 || short <= 0.0 {
564:                 return f64::MAX;
565:             }
566:             let (mx, mn) = (row.iter().cloned().fold(f64::MIN, f64::max), row.iter().cloned().fold(f64::MAX, f64::min));
567:             ((short * short * mx) / (s * s)).max((s * s) / (short * short * mn.max(1e-9)))
568:         };
569:         let mut j = i + 1;
570:         while j < areas.len() && worst(&areas[i..=j]) <= worst(&areas[i..j]) {
571:             j += 1;
572:         }
573:         let row = &areas[i..j];
574:         let s: f64 = row.iter().sum();
575:         if w >= h {
576:             let cw = s / h;
577:             let mut cy = y;
578:             for (k, a) in row.iter().enumerate() {
579:                 let ch = a / cw;
580:                 out[i + k] = (x, cy, cw, ch);
581:                 cy += ch;
582:             }
583:             x += cw;
584:             w -= cw;
585:         } else {
586:             let rh = s / w;
587:             let mut cx = x;
588:             for (k, a) in row.iter().enumerate() {
589:                 let cw = a / rh;
590:                 out[i + k] = (cx, y, cw, rh);
591:                 cx += cw;
592:             }
593:             y += rh;
594:             h -= rh;
595:         }
596:         i = j;
597:     }
598:     out
599: }
