118: /// A tiny lexer: comments, strings, numbers, a generic keyword list. Good enough to make unknown formats readable.
119: fn lex(src: &str, ext: &str) -> Vec<(usize, usize, Cls)> {
120:     let hash_comment = matches!(ext, "yaml" | "yml" | "conf" | "ini" | "cfg" | "env" | "rb" | "pl" | "mk" | "dockerfile" | "gitignore" | "txt" | "properties");
121:     let slash_comment = !hash_comment || matches!(ext, "ts" | "tsx" | "java" | "kt" | "swift" | "cpp" | "hpp" | "cc" | "cs" | "php" | "scss");
122:     let b = src.as_bytes();
123:     let mut out: Vec<(usize, usize, Cls)> = vec![];
124:     let push = |out: &mut Vec<(usize, usize, Cls)>, s: usize, e: usize, c: Cls| {
125:         if e > s {
126:             match out.last_mut() {
127:                 Some(l) if l.2 == c && l.1 == s => l.1 = e,
128:                 _ => out.push((s, e, c)),
129:             }
130:         }
131:     };
132:     let mut i = 0;
133:     while i < b.len() {
134:         let c = b[i];
135:         let start = i;
136:         if (hash_comment && c == b'#') || (slash_comment && c == b'/' && b.get(i + 1) == Some(&b'/')) || (ext == "sql" && c == b'-' && b.get(i + 1) == Some(&b'-')) {
137:             while i < b.len() && b[i] != b'\n' {
138:                 i += 1;
139:             }
140:             push(&mut out, start, i, Cls::Comment);
141:         } else if slash_comment && c == b'/' && b.get(i + 1) == Some(&b'*') {
142:             i += 2;
143:             while i + 1 < b.len() && !(b[i] == b'*' && b[i + 1] == b'/') {
144:                 i += 1;
145:             }
146:             i = (i + 2).min(b.len());
147:             push(&mut out, start, i, Cls::Comment);
148:         } else if c == b'"' || c == b'\'' || c == b'`' {
149:             i += 1;
150:             while i < b.len() && b[i] != c && b[i] != b'\n' {
151:                 if b[i] == b'\\' {
152:                     i += 1;
153:                 }
154:                 i += 1;
155:             }
156:             i = (i + 1).min(b.len());
157:             push(&mut out, start, i, Cls::Str);
158:         } else if c.is_ascii_digit() {
159:             while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'.' || b[i] == b'_') {
160:                 i += 1;
161:             }
162:             push(&mut out, start, i, Cls::Number);
163:         } else if c.is_ascii_alphabetic() || c == b'_' {
164:             while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
165:                 i += 1;
166:             }
167:             let w = &src[start..i];
168:             let cls = if KEYWORDS.contains(&w) {
169:                 Cls::Keyword
170:             } else if w.chars().next().is_some_and(|ch| ch.is_uppercase()) {
171:                 Cls::Type
172:             } else if b.get(i) == Some(&b'(') {
173:                 Cls::Function
174:             } else {
175:                 Cls::Plain
176:             };
177:             push(&mut out, start, i, cls);
178:         } else {
179:             // advance one full UTF-8 char
180:             i += 1;
181:             while i < b.len() && (b[i] & 0xC0) == 0x80 {
182:                 i += 1;
183:             }
184:             push(&mut out, start, i, if matches!(c, b'{' | b'}' | b'(' | b')' | b'[' | b']' | b';' | b',' | b'=' | b'<' | b'>' | b'+' | b'-' | b'*' | b'/' | b'&' | b'|' | b'!' | b':') { Cls::Punct } else { Cls::Plain });
185:         }
186:     }
187:     out
188: }
