210: /// A ready-to-draw layout job. `wrap` is the wrap width (`f32::INFINITY` for horizontal scrolling code).
211: pub fn layout(src: &str, ext: &str, dark: bool, font: FontId, wrap: f32) -> LayoutJob {
212:     let mut job = LayoutJob::default();
213:     job.wrap.max_width = wrap;
214:     let mut at = 0;
215:     for (s, e, c) in runs(src, ext) {
216:         if s > at {
217:             job.append(&src[at..s], 0.0, TextFormat { font_id: font.clone(), color: color(Cls::Plain, dark), ..Default::default() });
218:         }
219:         job.append(&src[s..e], 0.0, TextFormat { font_id: font.clone(), color: color(c, dark), italics: c == Cls::Comment, ..Default::default() });
220:         at = e;
221:     }
222:     if at < src.len() {
223:         job.append(&src[at..], 0.0, TextFormat { font_id: font, color: color(Cls::Plain, dark), ..Default::default() });
224:     }
225:     job
226: }
