use serde_json::Value;

#[derive(Clone, Debug, Default, PartialEq)]
pub struct VideoStream {
    pub index: usize,
    pub codec: String,
    pub width: u32,
    pub height: u32,
    pub fps: f64,
    pub bitrate: Option<u64>,
    pub pix_fmt: String,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct AudioStream {
    pub index: usize,
    pub codec: String,
    pub channels: u32,
    pub sample_rate: u32,
    pub lang: String,
    pub title: String,
    pub default: bool,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct SubStream {
    pub index: usize,
    pub codec: String,
    pub lang: String,
    pub title: String,
    pub default: bool,
    pub forced: bool,
}

impl SubStream {
    /// Text subtitles can be extracted and rendered; bitmap ones (PGS, VobSub) cannot.
    pub fn is_text(&self) -> bool {
        matches!(self.codec.as_str(), "subrip" | "srt" | "ass" | "ssa" | "webvtt" | "mov_text" | "text")
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct MediaInfo {
    pub title: String,
    pub container: String,
    pub duration: f64,
    pub size: u64,
    pub bitrate: u64,
    pub video: Vec<VideoStream>,
    pub audio: Vec<AudioStream>,
    pub subs: Vec<SubStream>,
    pub chapters: Vec<(f64, String)>,
}

impl MediaInfo {
    pub fn primary_video(&self) -> Option<&VideoStream> {
        self.video.first()
    }
    pub fn size_wh(&self) -> (u32, u32) {
        self.primary_video().map(|v| (v.width, v.height)).unwrap_or((0, 0))
    }
    pub fn fps(&self) -> f64 {
        self.primary_video().map(|v| v.fps).filter(|f| *f > 1.0).unwrap_or(25.0)
    }
}

fn parse_rate(s: &str) -> f64 {
    match s.split_once('/') {
        Some((n, d)) => {
            let (n, d): (f64, f64) = (n.parse().unwrap_or(0.0), d.parse().unwrap_or(0.0));
            if d > 0.0 {
                n / d
            } else {
                0.0
            }
        }
        None => s.parse().unwrap_or(0.0),
    }
}
