# ─── Volume Clone ─────────────────────────────────────────────

struct CloneVolumeRequest {
    # Source volume to clone.
    sourceVolumeId @0 :T.VolumeId;
    # Name for the cloned volume.
    name @1 :Text;
    # Target pool (empty = same pool as source).
    targetPoolId @2 :T.StoragePoolId;
