    # -- Audit-9: Camera stream routing --
    routeStream @24 (cameraId :T.CameraId, route :CameraStreamRoute) -> T.VoidResult;
    listStreamRoutes @25 (cameraId :T.CameraId) -> (routes :List(CameraStreamRoute));

