    getRichMetadata @28 (captureId :T.CaptureId) -> (metadata :RichPhotoMetadata);

    # -- Audit-9: Camera firmware/hardware info --
    getHardwareInfo @29 (cameraId :T.CameraId) -> (info :CameraHardwareInfo);

