//! The scan: a cheap listing in bulk, the expensive thing second.
//!
//! §11.2's three deliberate restraints: a directory listing is cheap and a
//! stat-and-probe per file is not; symlinks are not followed, because a symlink
//! loop in a photo library is a real and recurring problem; and hidden files are
//! skipped, because screenshot tools write to `~/.cache` and
//! `Pictures/.thumbnails` is not the user's photographs.

use std::path::{Path, PathBuf};

use crate::index::{IndexSnapshot, PER_ROOT_CEILING, SCAN_DEPTH};
use crate::media;
use crate::model::{Kind, Photo, PhotoId, Source, TakenSource};

/// A scan's own knobs, and they are the caller's because a test states its input
/// rather than guessing it.
#[derive(Clone, Debug)]
pub struct ScanOptions {
    pub follow_links: bool,
    pub include_hidden: bool,
    pub depth: usize,
    pub ceiling: usize,
    /// Stop after this many files. Cancelling **keeps** what has been found,
    /// because half an index is useful and a discarded one is not.
    pub limit: Option<usize>,
    pub hash_prefix: bool,
}

impl Default for ScanOptions {
    fn default() -> Self {
        Self {
            follow_links: false,
            include_hidden: false,
            depth: SCAN_DEPTH,
            ceiling: PER_ROOT_CEILING,
            limit: None,
            hash_prefix: true,
        }
    }
}

impl ScanOptions {
    /// A scan with no duplicate hash: a first launch, or a library where the
    /// duplicates collection is off.
    #[must_use]
    pub fn quick() -> Self {
        Self { hash_prefix: false, ..Self::default() }
    }
}

/// What the scan emits. `Found` carries a partial result, which is the state a
/// scan spends six minutes in.
#[derive(Clone, Debug, PartialEq)]
pub enum ScanEvent {
    Started { sources: usize },
    Found { photo: Box<Photo> },
    Skipped,
    Progress { found: u32 },
    Finished(Box<IndexSnapshot>),
    Cancelled(Box<IndexSnapshot>),
    Failed(String),
}

/// Whether a directory entry is a photograph at all.
///
/// `.xmp` sidecars are the trap: a naive extension filter shows the sidecar as a
/// photograph and the library count is 30 % wrong, so a sidecar is never indexed
/// as a photograph — it is bound to its base image.
#[must_use]
pub fn classify(name: &str) -> Option<Kind> {
    let extension = Path::new(name).extension()?.to_str()?;
    if extension.eq_ignore_ascii_case("xmp") {
        return None;
    }
    Kind::from_extension(extension)
}

/// A sidecar base name: `IMG_0001.jpg` and `IMG_0001.jpg.xmp` are the same
/// photograph, and `IMG_0001.xmp` is `IMG_0001`'s sidecar in `lr` mode.
#[must_use]
pub fn sidecar_base(name: &str) -> Option<String> {
    let lowered = name.to_lowercase();
    lowered.strip_suffix(".xmp").map(str::to_owned)
}

/// Every file under `root` that is a photograph, in listing order and without a
/// `stat` per file. Enumeration is the cheap part and it is done in bulk.
#[must_use]
pub fn enumerate(root: &Path, options: &ScanOptions) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let walker = walkdir::WalkDir::new(root)
        .follow_links(options.follow_links)
        .max_depth(options.depth)
        .into_iter()
        .filter_entry(|entry| {
            options.include_hidden || !entry.file_name().to_string_lossy().starts_with('.')
        });
