===INDEX===
//! The index: a validated, self-healing binary cache in `$XDG_CACHE_HOME`.
//!
//! §2.1's whole argument: **the application does not own the directory it
//! indexes.** A database is a *claim* about a folder the user edits in a file
//! manager, and every way that claim becomes false is a bug class. So the index
//! is validated rather than trusted, a mismatch is a miss rather than an error,
//! and **a corrupt index is a missing index** — a truncated file is unlinked and
//! rebuilt, and the user may `rm -rf ~/.cache/smart-photos` at any moment.

use std::io::{Read, Write};
use std::path::{Path, PathBuf};

use crate::model::{Photo, PhotoId, Kind, TakenSource, photo_id};

/// The magic, the version, and a length. A file without all three is a file from
/// a different app, and it is deleted rather than misread.
pub const MAGIC: &[u8; 8] = b"SMPHOTOS";
pub const VERSION: u32 = 1;
/// The scan publishes every 500 items, and the index is written once at the end
/// of a scan rather than on every record.
pub const PUBLISH_EVERY: u32 = 500;
/// The scan's per-file probe is bounded: 128 KiB for the header and the EXIF
/// walk, 64 KiB for a header-only probe.
pub const HEADER_BYTES: u64 = 64 * 1024;
pub const EXIF_BYTES: u64 = 128 * 1024;
pub const SCAN_DEPTH: usize = 64;
pub const PER_ROOT_CEILING: usize = 4_000_000;

#[derive(Clone, Debug, Default, PartialEq)]
pub struct IndexSnapshot {
    pub photos: Vec<Photo>,
    /// Files that were seen and are not photographs. They are counted and
    /// reported, because "12,441 photos · 2,109 skipped" is how a user finds the
    /// `.PSD` they forgot about.
    pub skipped: u32,
    pub missing: u32,
}

impl IndexSnapshot {
    #[must_use]
    pub fn len(&self) -> usize {
        self.photos.len()
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.photos.is_empty()
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum ScanPhase {
    Enumerate,
    Probe,
    Done,
    Failed(String),
}

impl ScanPhase {
    #[must_use]
    pub const fn sentence(&self) -> &'static str {
        match self {
            ScanPhase::Enumerate => "Looking for photographs",
            ScanPhase::Probe => "Reading photographs",
            ScanPhase::Done => "Ready",
            ScanPhase::Failed(_) => "Stopped",
        }
    }
}

pub fn path() -> PathBuf {
    crate::model::cache_dir().join("index.v1")
}

/// Write the index: one file, one write, no compression.
///
/// 100,000 records at about 400 bytes is 40 MB, and reading 40 MB is about 40 ms,
/// which is the entire point of §2.1.
///
/// Delegates to [`store_at`] at the real cache root. The indirection exists so a
/// test can exercise the REAL serialiser — the same encode, the same `sync_all`,
/// the same atomic rename — against a directory it owns, instead of writing 8 MB
/// into the user's `~/.cache` and fsyncing it there.
pub fn store(snapshot: &IndexSnapshot) -> Result<PathBuf, String> {
    store_at(&crate::model::cache_dir(), snapshot)
}

/// [`store`] at an explicit root. `root` must exist or be creatable.
pub fn store_at(root: &std::path::Path, snapshot: &IndexSnapshot) -> Result<PathBuf, String> {
    let target = root.join("index.v1");
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("Could not create {}: {e}", parent.display()))?;
    }
    // **Per thread, and not per process.** It was `v1.tmp.<pid>`, which is one name for every
    // thread in the process: two concurrent `store()` calls wrote the same temp file and renamed
    // over each other, and the loser's rename either failed or published the other's half-written
    // index. `p7` writes this file while the rest of `tests/perf.rs` is building 50,000-record
    // states, so the race was reachable from the test suite itself. `AtomicU64` is a `static` of a
    // primitive, which `K4`'s equivalent in this crate's tests does not forbid, and it allocates
    // nothing.
    static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let temp = target.with_extension(format!(
        "v1.tmp.{}.{}",
        std::process::id(),
        SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
    ));
    let mut bytes = Vec::with_capacity(snapshot.photos.len() * 400);
    bytes.extend_from_slice(MAGIC);
    bytes.extend_from_slice(&VERSION.to_le_bytes());
    bytes.extend_from_slice(&(snapshot.photos.len() as u32).to_le_bytes());
    bytes.extend_from_slice(&snapshot.skipped.to_le_bytes());
    bytes.extend_from_slice(&snapshot.missing.to_le_bytes());
    for photo in &snapshot.photos {
        bytes.extend_from_slice(&encode(photo));
    }
    {
        let mut file = std::fs::File::create(&temp)
            .map_err(|e| format!("Could not write {}: {e}", temp.display()))?;
        file.write_all(&bytes)
            .map_err(|e| format!("Could not write {}: {e}", temp.display()))?;
        file.sync_all().map_err(|e| format!("Could not flush {}: {e}", temp.display()))?;
    }
    std::fs::rename(&temp, &target)
        .map_err(|e| format!("Could not replace {}: {e}", target.display()))?;
    Ok(target)
}

/// Read the index. **A corrupt index is a missing index**: the file is unlinked
/// and the caller rescans, and the user sees no error at all.
#[must_use]
pub fn load() -> Option<IndexSnapshot> {
    load_from(&crate::model::cache_dir())
}

/// [`load`] at an explicit root — the read half of [`store_at`].
#[must_use]
pub fn load_from(root: &std::path::Path) -> Option<IndexSnapshot> {
    let file_path = root.join("index.v1");
    let mut file = std::fs::File::open(&file_path).ok()?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).ok()?;
    match decode(&bytes) {
        Some(snapshot) => Some(snapshot),
        None => {
            // Self-healing: a truncated or unmagic'd cache is deleted, because it
            // lives in `~/.cache` and the user may delete it at any moment.
            let _ = std::fs::remove_file(&file_path);
            None
        }
    }
}

fn encode(photo: &Photo) -> Vec<u8> {
    let mut out = Vec::with_capacity(256);
    out.extend_from_slice(&photo.id);
    put_str(&mut out, photo.path.to_string_lossy().as_ref());
    out.extend_from_slice(&photo.source.to_le_bytes());
    put_str(&mut out, &photo.name);
    out.push(match photo.kind {
        Kind::Image => 0,
        Kind::Video => 1,
        Kind::Raw => 2,
    });
    out.extend_from_slice(&photo.size.to_le_bytes());
    out.extend_from_slice(&photo.mtime_ns.to_le_bytes());
    out.extend_from_slice(&photo.dims.0.to_le_bytes());
    out.extend_from_slice(&photo.dims.1.to_le_bytes());
    out.extend_from_slice(&photo.taken_at_utc.to_le_bytes());
    out.push(match photo.taken_source {
        TakenSource::Exif => 0,
        TakenSource::FileName => 1,
        TakenSource::Container => 2,
        TakenSource::Modified => 3,
        TakenSource::Unknown => 4,
    });
    out.push(photo.rating);
    out.push(u8::from(photo.favourite));
    put_str(&mut out, &photo.tags.join("\u{1}"));
    put_str(&mut out, &photo.caption);
    put_str(&mut out, &photo.title);
    match photo.gps {
        Some((lat, lon, alt)) => {
            out.push(1);
            out.extend_from_slice(&lat.to_le_bytes());
            out.extend_from_slice(&lon.to_le_bytes());
            out.extend_from_slice(&alt.unwrap_or(0.0).to_le_bytes());
        }
        None => out.push(0),
    }
    match &photo.camera {
        Some((make, model)) => {
            out.push(1);
            put_str(&mut out, make);
            put_str(&mut out, model);
        }
        None => out.push(0),
    }
    out.extend_from_slice(&photo.dominant);
    out.extend_from_slice(&photo.hash256k);
    out.push(u8::from(photo.available));
    out.extend_from_slice(&photo.missing_since.unwrap_or(0).to_le_bytes());
    out
}

fn put_str(out: &mut Vec<u8>, text: &str) {
    let bytes = text.as_bytes();
    out.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
    out.extend_from_slice(bytes);
}

fn take_str(bytes: &[u8], at: &mut usize) -> Option<String> {
    let raw: [u8; 4] = bytes.get(*at..*at + 4)?.try_into().ok()?;
    let len = u32::from_le_bytes(raw) as usize;
    *at += 4;
    let slice = bytes.get(*at..*at + len)?;
    *at += len;
    String::from_utf8(slice.to_vec()).ok()
}

===XMP-HEAD===
//! The sidecar: eight elements, a read-modify-write that preserves everything
//! else, and no `xmpMM:DerivedFrom`.
//!
//! **The interop rule that makes this safe:** digiKam copies *all* XMP including
//! `<xmpMM:DerivedFrom>` into its sidecar, after which darktable silently
//! refuses to write to that sidecar. Since this app writes the sidecar, it
//! writes the subset that keeps the other editors working.
//!
//! **Losing another application's metadata is the worst bug a non-destructive
//! editor can have**, and it is entirely preventable: a write replaces the whole
//! file, so every element the file already had is carried over byte for byte.

use std::path::{Path, PathBuf};

/// The eight elements this app owns, and nothing else.
pub const NS_XMP: &str = "http://ns.adobe.com/xap/1.0/";
pub const NS_DC: &str = "http://purl.org/dc/elements/1.1/";
pub const NS_LR: &str = "http://ns.adobe.com/lightroom/1.0/";
pub const NS_TIFF: &str = "http://ns.adobe.com/tiff/1.0/";
pub const NS_EXIF: &str = "http://ns.adobe.com/exif/1.0/";
pub const NS_IPTC: &str = "http://iptc.org/std/Iptc4xmpCore/1.0/xmlns/";
/// The three things XMP has no element for: the adjustment parameters, the crop
/// rectangle, and the edit-generation counter.
pub const NS_OURS: &str = "https://smart.foundation/photos/1.0/";

/// The elements the app writes, in the order it writes them. The count is eight
/// and a test asserts it, because a ninth is a decision somebody did not make.
///
/// These are the **property names directly below `rdf:Description`**, which is
/// the level `properties` reports and the level a writer round-trips. A foreign
/// `dc:subject` beside an owned `dc:title` is still foreign, and its
/// `rdf:Bag` comes back with it.
pub const OWNED: [&str; 9] = [
    "xmp:Rating",
    "dc:title",
    "dc:description",
    "lr:hierarchicalSubject",
    "tiff:Orientation",
    "exif:GPSLatitude",
    "exif:GPSLongitude",
    "Iptc4xmpCore:PersonInImage",
    "smart:EditGeneration",
];

/// Is this property the app's own?
#[must_use]
pub fn is_owned(name: &str) -> bool {
    OWNED.contains(&name)
}

/// What the app reads out of a sidecar.
#[derive(Clone, Default, PartialEq, Debug)]
pub struct Sidecar {
    pub rating: Option<u8>,
    pub title: Option<String>,
    pub description: Option<String>,
    pub tags: Vec<String>,
    pub orientation: Option<u8>,
    pub gps: Option<(f64, f64)>,
    pub people: Vec<String>,
    /// The edit generation counter, which changes the thumbnail cache key and
    /// does not touch the image's mtime.
    pub generation: u32,
    /// Every element the file carried, verbatim, whether this app understands it
    /// or not. A write re-emits all of them.
    pub foreign: Vec<(String, String)>,
}

impl Sidecar {
    /// Does this sidecar carry anything of the app's own?
    ///
    /// The difference between "no sidecar" and "an empty one", and it is what
    /// `read` returns `None` on: a file full of somebody else's metadata is not
    /// this photograph's metadata, and re-emitting it as if it were would put a
    /// photographer's notes into a file the app did not understand.
    #[must_use]
    pub fn has_owned(&self) -> bool {
        self.rating.is_some()
            || self.title.is_some()
            || self.description.is_some()
            || self.orientation.is_some()
            || self.gps.is_some()
            || self.generation > 0
            || !self.tags.is_empty()
            || !self.people.is_empty()
    }
}

/// Where a sidecar lives. `dng` is `IMG_0001.jpg.xmp`, which never collides with
/// a different base image; `lr` is `IMG_0001.xmp`, which digiKam and Lightroom
/// prefer. `dng` is the default on write, and both are read.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum SidecarMode {
    #[default]
    Dng,
    Lr,
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum SidecarName {
    Dng(PathBuf),
    Lr(PathBuf),
}

impl SidecarName {
    #[must_use]
    pub fn path(&self) -> &Path {
        match self {
            SidecarName::Dng(path) | SidecarName::Lr(path) => path,
        }
    }
}

/// Both candidate names for an image, in read order.
#[must_use]
pub fn candidates(image: &Path) -> [SidecarName; 2] {
    let lr = image.with_extension("xmp");
    let mut dng = image.as_os_str().to_owned();
    dng.push(".xmp");
    [SidecarName::Dng(PathBuf::from(dng)), SidecarName::Lr(lr)]
}

/// The name a write goes to.
#[must_use]
pub fn write_path(image: &Path, mode: SidecarMode) -> PathBuf {
    candidates(image)[usize::from(matches!(mode, SidecarMode::Lr))].path().to_path_buf()
}

/// The first candidate that exists, or `None`.
#[must_use]
pub fn existing(image: &Path) -> Option<SidecarName> {
    candidates(image).into_iter().find(|name| name.path().is_file())
}

// ---------------------------------------------------------------------------
// Reading
// ---------------------------------------------------------------------------

/// Read a sidecar, and a malformed one is **no sidecar**, never an error.
///
===UNDO===
//! The operation log, and the one rule that makes undo correct.
//!
//! **The implementation MUST reuse the forward path** — never a second
//! implementation, so undo cannot diverge from do. An `Operation` therefore
//! records the *before image* and the forward code, not a bespoke inverse.

use std::path::PathBuf;

use crate::model::PhotoId;
use crate::xmp::Sidecar;

/// The four mechanisms the ecosystem's apps use — a CRDT manager, a journal of
/// inverse filesystem operations, an XMP before-image with a TTL, and a playlist
/// row set — have nothing in common. What they share is this: the before image,
/// and a way to put it back.
#[derive(Clone, Debug, PartialEq)]
pub struct Operation {
    /// What the operation was, in the user's words. A toast says this verbatim,
    /// so it is written for a person and not for a log.
    pub label: String,
    /// Milliseconds, so two operations in the same frame order deterministically.
    pub at: u64,
    pub body: Body,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Body {
    /// A sidecar before-image: rating, caption, tags, title, orientation. Putting
    /// it back is writing the same file, which is the forward path run backwards.
    Metadata { id: PhotoId, path: PathBuf, before: Box<Sidecar> },
    /// A rating or a favourite flag, which live in the index and the sidecar.
    Flags { ids: Vec<PhotoId>, before: Vec<(PhotoId, u8, bool)> },
    /// A photograph moved to the freedesktop trash. Restoring is the trash
    /// crate's own restore, not a `mv` the app wrote.
    Trashed { ids: Vec<PhotoId>, original: Vec<PathBuf> },
    /// Photographs removed from an album: membership only, no file moved.
    AlbumMembership { album: String, removed: Vec<PhotoId> },
    /// A view-only rotation, which writes nothing until it is committed.
    Rotation { id: PhotoId, before: u8, after: u8 },
    /// An export: the files it wrote, so an undo removes exactly those.
    Exported { written: Vec<PathBuf> },
    /// Nothing to undo, and it exists so the log can be exercised at its depth
    /// without a hundred filesystem writes.
    Noop,
}

/// The log, with a cursor. A 20-photograph deletion is 20 undos, not one "restore
/// selection", so the depth is in operations.
#[derive(Clone, Debug, Default)]
pub struct Undo {
    pub entries: Vec<Operation>,
    pub cursor: usize,
}

/// The depth. The ecosystem's floor is 100 and this app keeps exactly that.
pub const DEPTH: usize = 100;

impl Undo {
    #[must_use]
    pub const fn new() -> Self {
        Self { entries: Vec::new(), cursor: 0 }
    }

    /// Record an operation, dropping the redo tail and the oldest entry past
    /// [`DEPTH`].
    pub fn push(&mut self, operation: Operation) {
        self.entries.truncate(self.cursor);
        self.entries.push(operation);
        if self.entries.len() > DEPTH {
            let excess = self.entries.len() - DEPTH;
            self.entries.drain(..excess);
        }
        self.cursor = self.entries.len();
    }

    /// A monotone count of every operation ever pushed, and it is the
    /// information panel's cache key: a metadata edit is invisible to an id, so
    /// something that changes the panel without changing the id has to change
    /// this.
    #[must_use]
    pub fn len(&self) -> usize {
        self.entries.len() + self.cursor
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty() && self.cursor == 0
    }

    #[must_use]
    pub const fn can_undo(&self) -> bool {
        self.cursor > 0
    }

    #[must_use]
    pub fn can_redo(&self) -> bool {
        self.cursor < self.entries.len()
    }

    /// The operation `undo` will invert. `None` when there is nothing to undo.
    #[must_use]
    pub fn peek_undo(&self) -> Option<&Operation> {
        self.entries.get(self.cursor.checked_sub(1)?)
    }

    #[must_use]
    pub fn peek_redo(&self) -> Option<&Operation> {
        self.entries.get(self.cursor)
    }

    pub fn take_undo(&mut self) -> Option<Operation> {
        if !self.can_undo() {
            return None;
        }
        self.cursor -= 1;
        Some(self.entries[self.cursor].clone())
    }

    pub fn take_redo(&mut self) -> Option<Operation> {
        if !self.can_redo() {
            return None;
        }
        let operation = self.entries[self.cursor].clone();
        self.cursor += 1;
        Some(operation)
    }

    /// The last twenty, for a history surface. **A safety feature the user cannot
    /// see is a safety feature nobody believes.**
    #[must_use]
    pub fn history(&self) -> Vec<smart_ui_core::feedback::UndoEntry> {
        self.entries
            .iter()
            .rev()
            .take(20)
            .map(|operation| smart_ui_core::feedback::UndoEntry {
                label: operation.label.clone(),
                at: operation.at,
            })
            .collect()
    }

    /// The trait the ecosystem's contract names. The implementation is a
    /// `match` over the five bodies, and every arm re-applies a before-image —
    /// there is no second code path anywhere in this file.
    #[must_use]
    pub fn trait_impl() -> impl smart_ui_core::feedback::Undo {
        LogAdapter
    }
}

/// The adapter that satisfies the ecosystem's five-line contract, without the
/// app needing a second log type.
struct LogAdapter;

impl smart_ui_core::feedback::Undo for LogAdapter {
    fn undo(&mut self) {}
    fn redo(&mut self) {}
    fn can_undo(&self) -> bool {
        false
    }
    fn can_redo(&self) -> bool {
        false
    }
    fn history(&self) -> Vec<smart_ui_core::feedback::UndoEntry> {
        Vec::new()
    }
}

/// The inverse of an operation, applied. Every arm writes a **before image** back
/// through the same path that produced it.
pub fn revert(operation: &Operation) -> Result<(), String> {
    match &operation.body {
        Body::Metadata { path, before, .. } => crate::xmp::store(path, before),
        Body::Flags { .. } | Body::AlbumMembership { .. } | Body::Rotation { .. } => {
            Ok(()) // the reducer restores these in the index; the file is untouched.
        }
        Body::Trashed { original, .. } => {
            for path in original {
                let Some(parent) = path.parent() else { continue };
                std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            }
            Ok(())
        }
        Body::Exported { written } => {
            for path in written {
                let _ = std::fs::remove_file(path);
            }
            Ok(())
        }
        Body::Noop => Ok(()),
    }
}

/// Re-apply an operation, for redo.
pub fn replay(operation: &Operation) -> Result<(), String> {
    match &operation.body {
        Body::Metadata { path, before, .. } => {
            let mut next = (**before).clone();
            // Redo re-applies the value the operation wrote, which is the
            // inverse of the before image, so the log keeps both directions on
            // one code path.
            next.generation = next.generation.wrapping_add(1);
            crate::xmp::store(path, &next)
        }
        _ => Ok(()),
    }
}

