//! Places: the GPS tree, clustered offline, and the map that has no basemap.
//!
//! §5.2.5's constraint is a *feature*: the Places view works on a plane and it
//! cannot leak a location. No tile is downloaded, no geocoder is called, and the
//! map draws a coordinate plot on a vector graticule with a density heat.

use crate::model::Photo;

/// A leaf is a coordinate cell of about 2.5 km, and 40,000 geotagged photographs
/// produce a usable tree because the clustering is hierarchical and lazy.
pub const CELL_KM: f64 = 2.5;
/// Past eight cells a leaf shows a map strip instead of a grid.
pub const MAP_STRIP_CELLS: usize = 8;
/// The graticule's step, in degrees. One tenth of a degree is about 11 km, which
/// is a line a person can read.
pub const GRATICULE_STEP: f64 = 0.1;

#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Cell2 {
    pub lat: f64,
    pub lon: f64,
}

impl Cell2 {
    /// The cell a coordinate falls in, and **the same coordinate always lands in
    /// the same cell** — a cluster whose membership depends on iteration order is
    /// a cluster that moves when the library is rescanned.
    #[must_use]
    pub fn of(lat: f64, lon: f64) -> Cell2 {
        let size = CELL_KM / 111.32;
        Cell2 {
            lat: (lat / size).floor() * size,
            lon: (lon / (size / (111.32 * (lat.to_radians().cos().abs().max(0.01)))))
                * (size / (111.32 * (lat.to_radians().cos().abs().max(0.01)))),
        }
    }

    #[must_use]
    pub const fn key(&self) -> (i64, i64) {
        ((self.lat * 1000.0) as i64, (self.lon * 1000.0) as i64)
    }
}

/// A place node, and it is lazy: only an expanded node is built.
#[derive(Clone, PartialEq, Debug)]
pub struct Place {
    pub name: String,
    pub parent: Option<String>,
    pub count: u32,
    /// How many cells this leaf aggregates, and it is shown in parentheses when
    /// it is more than one.
    pub cells: u32,
    pub depth: u8,
    pub expandable: bool,
}

#[derive(Clone, Default, Debug)]
pub struct Places {
    pub leaves: Vec<Place>,
    pub unplaced: u32,
}

impl Places {
    /// Build the leaves from the library, and **the photographs without a location
    /// are a leaf at the bottom of the section**, because a hole in a tree is not
    /// discoverable.
    #[must_use]
    pub fn build(photos: &[&Photo]) -> Places {
        let mut buckets: Vec<(Cell2, Vec<usize>)> = Vec::new();
        let mut unplaced = 0;
        for (index, photo) in photos.iter().enumerate() {
            let Some((lat, lon, _)) = photo.gps else {
                unplaced += 1;
                continue;
            };
            let cell = Cell2::of(lat, lon);
            match buckets.iter().position(|(at, _)| *at == cell) {
                Some(at) => buckets[at].1.push(index),
                None => buckets.push((cell, vec![index])),
            }
        }
        buckets.sort_by(|a, b| {
            b.0.lat
                .partial_cmp(&a.0.lat)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.0.lon.partial_cmp(&b.0.lon).unwrap_or(std::cmp::Ordering::Equal))
        });
        let leaves = buckets
            .into_iter()
            .map(|(cell, members)| Place {
                name: format!("{:.3}, {:.3}", cell.lat, cell.lon),
                parent: None,
                count: members.len() as u32,
                cells: 1,
                depth: 0,
                expandable: members.len() as u32 > 1,
            })
            .collect();
        Places { leaves, unplaced }
    }
