    #[default]
    User,
    Marquee,
    Find,
    Filter,
}

/// How a marquee merges with what is already held.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Merge {
    Replace,
    Add,
    Subtract,
}

#[derive(Clone, Debug, Default)]
pub struct Selection {
    /// The `Shift+Click` anchor. **Never an index.**
    pub anchor: Option<PhotoId>,
    /// The roving focus cell, which is a different thing: focus is where the
    /// keyboard is, and `Ctrl+Arrow` moves it without changing the selection.
    pub focus: Option<PhotoId>,
    pub held: HashSet<PhotoId>,
    /// Click order, for "export in click order".
    pub order: Vec<PhotoId>,
    pub source: SelectionSource,
}

impl Selection {
    #[must_use]
    pub fn new() -> Self {
        Self { anchor: None, focus: None, held: HashSet::new(), order: Vec::new(), source: SelectionSource::User }
    }

    #[must_use]
    pub fn len(&self) -> usize {
        self.held.len()
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.held.is_empty()
    }

    #[must_use]
    pub fn contains(&self, id: &PhotoId) -> bool {
        self.held.contains(id)
    }

    /// `uniform` is `kind != Mixed`: a rating applied to a mixed set has no
    /// meaning, and the command is `Unavailable` rather than a guess.
    #[must_use]
    pub fn uniform_kind(&self, kinds: impl Fn(&PhotoId) -> Kind) -> bool {
        let mut kind: Option<Kind> = None;
        for id in &self.order {
            let current = kinds(id);
            if kind.is_some_and(|first| first != current) {
                return false;
            }
            kind = Some(current);
        }
        true
