    }

    /// A click replaces the selection and sets the anchor and the focus.
    pub fn click(&mut self, id: PhotoId) {
        self.held.clear();
        self.held.insert(id);
        self.order.clear();
        self.order.push(id);
        self.anchor = Some(id);
        self.focus = Some(id);
        self.source = SelectionSource::User;
    }

    /// `Ctrl+Click` toggles, and **the selection is not released if it would be
    /// empty** — a selection the user cannot see is a selection they cannot undo.
    pub fn toggle(&mut self, id: PhotoId) {
