//! The timeline's four grid layouts, and the offsets they resolve to.
//!
//! `Grid` and `Flat` have closed-form `O(1)` offsets, so the scrollbar is exact
//! and a resize costs a subtraction. Justified and Masonry genuinely change with
//! width, so they are measured incrementally and cached in a [`RowMap`], and the
//! map is a prefix sum rather than a row count because masonry's scroll height
//! is variable.

use super::{Photo, PhotoId};
use std::cmp::Reverse;
use std::path::Path;
use std::collections::HashSet;

use smart_ui_core::layout::Sp;

pub const MAX_COLS: usize = 12;
/// A cell may not exceed this multiple of `min_cell`.
///
/// Nothing reduces `cols` to enforce it — see [`square_cols`] — because
/// `MAX_CONTENT_WIDTH` and `MAX_COLS` already keep every reachable cell inside it.
/// The constant stays because it is the invariant those two are chosen to satisfy,
/// and `G4` asserts it at every width.
pub const CELL_CEILING: f32 = 1.35;
/// The grid's gap. Four points, and it is the only spacing value this app invents.
pub const GAP: Sp = 4.0;
pub const GAP_COMPACT: Sp = 6.0;
pub const MIN_CELL_COMFORTABLE: Sp = 96.0;
pub const MIN_CELL_LARGE: Sp = 144.0;
pub const MIN_CELL_COMPACT: Sp = 64.0;
