#[derive(Clone, Copy, PartialEq, Debug)]
pub struct GridSpec {
    pub width: Sp,
    pub gap: Sp,
    pub min_cell: Sp,
}

impl GridSpec {
    /// **The one entry point.** The cell floor is the frame's, read from the
    /// width's rung, and every caller — the state, the hit test, the painter and
    /// every test — goes through here. Three places that each built this literal
    /// is three places that can disagree about the column count, and a grid that
    /// hit-tests four columns and paints five is a grid where clicks land on the
    /// wrong photograph.
    #[must_use]
    pub const fn for_width(width: Sp, compact: bool) -> Self {
        // One floor per density, and **not** a bigger one at the large rung.
        // `MIN_CELL_LARGE` existed to stop a 96 px cell becoming seventeen columns
        // on a 1600 px screen, and it did that job twice over: the content plane
        // stops at `MAX_CONTENT_WIDTH` and the count stops at `MAX_COLS`, so the
        // cell at the widest layout is already ~130 px. Keeping the bump only
        // bought a second discontinuity — twelve columns became eight at 1480 px,
        // and `G2` (a grid never loses a column as the window grows) is a law
        // while "bigger cells on a big screen" was a preference.
        let min_cell = if compact { MIN_CELL_COMPACT } else { MIN_CELL_COMFORTABLE };
        Self { width, gap: if compact { GAP_COMPACT } else { GAP }, min_cell }
    }
}
