#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Zoom {
    /// The whole image visible. The state on open.
    Fit,
    /// Covers the viewport, crops.
    Fill,
    One,
    Two,
    Three,
    Free(f32),
}

impl Zoom {
    pub const PRESETS: [Zoom; 5] = [Zoom::Fit, Zoom::Fill, Zoom::One, Zoom::Two, Zoom::Three];

    #[must_use]
    pub const fn scale(self, image: (u32, u32), viewport: (Sp, Sp)) -> f32 {
        match self {
            Zoom::Fit | Zoom::Fill => {
                if image.0 == 0 || image.1 == 0 || viewport.0 <= 0.0 || viewport.1 <= 0.0 {
                    return 1.0;
                }
                let sx = viewport.0 / image.0 as f32;
                let sy = viewport.1 / image.1 as f32;
                if matches!(self, Zoom::Fit) {
                    if sx < sy { sx } else { sy }
                } else if sx > sy {
                    sx
                } else {
                    sy
                }
            }
            Zoom::One => 1.0,
            Zoom::Two => 2.0,
            Zoom::Three => 3.0,
            Zoom::Free(factor) => factor,
        }
    }

    #[must_use]
    pub const fn is_fit(self) -> bool {
        matches!(self, Zoom::Fit)
    }
}

/// The zoom-to-cursor formula, and the whole of it.
///
/// A viewport point is `image_point * scale + pan`, so a zoom from `old` to `new`
/// that holds the point under the cursor still needs
///
/// ```text
/// pan_new = c - (c - pan) * (new / old)
/// ```
///
/// **The first argument is the pan, not the image point**, and the two are not
/// interchangeable: mixing them subtracts a viewport coordinate from an image
/// coordinate, which is dimensionally meaningless and drifts further on every
/// press. It is invisible on one zoom and unmistakable on twenty, and it is the
/// reason this function takes the pan and the scale rather than the cursor alone.
///
/// Scroll wheel and pinch both go through it, and **a pinch must not also pan**:
/// a two-finger gesture that both zooms and translates feels broken at every
/// zoom level.
#[must_use]
pub fn zoom_about(pan: (Sp, Sp), cursor: (Sp, Sp), old: f32, new: f32) -> (Sp, Sp) {
    if new <= 0.0 || old <= 0.0 {
        return pan;
    }
    let ratio = new / old;
    (cursor.0 - (cursor.0 - pan.0) * ratio, cursor.1 - (cursor.1 - pan.1) * ratio)
}

/// The image point under a viewport point, at a scale and a pan.
///
/// The forward of [`to_viewport`], and it lives here rather than on the state so a
/// test can state a cursor, a pan and a scale and read the point — which is the
/// only way `G25` can be written without a window.
#[must_use]
pub fn image_point(image: (Sp, Sp), scale: f32, pan: (Sp, Sp), cursor: (Sp, Sp)) -> (Sp, Sp) {
    let _ = image;
    (
        (cursor.0 - pan.0) / scale.max(1e-6),
        (cursor.1 - pan.1) / scale.max(1e-6),
    )
}

