//! Finding photos on disk. Filesystem access lives here and nowhere else, so the view can
//! stay declarative and this can be tested against real directories.

use crate::model::{Library, Photo, is_image};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

/// Reads the header to get a width and height. Only the header is parsed, not the pixels —
/// GPUI does the decoding when it paints. A file that cannot be read still gets listed; it
/// just cannot be fitted to the window.
fn dimensions(path: &Path) -> Option<(u32, u32)> {
    image::image_dimensions(path).ok()
}

/// Every image directly inside `dir`. Non-recursive, so a folder of 50,000 files does not
/// stall the UI. Unreadable files are skipped rather than aborting the whole listing.
pub fn scan(dir: &Path) -> Library {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return Library::default();
    };

    let mut photos: Vec<Photo> = entries
        .filter_map(|entry| {
            let entry = entry.ok()?;
            let path = entry.path();

            // `is_dir` first: a directory called `backup.png` is not a photo.
            let metadata = std::fs::metadata(&path).ok()?;
            if !metadata.is_file() || !is_image(&path) {
                return None;
            }

            Some(Photo {
                name: path.file_name()?.to_string_lossy().into_owned(),
                bytes: metadata.len(),
                dims: dimensions(&path),
                modified: metadata.modified().ok().or(Some(SystemTime::UNIX_EPOCH)),
                path,
            })
        })
        .collect();

    photos.sort_by(|a, b| a.name.to_lowercase().cmp(&b.name.to_lowercase()));
    Library::from_photos(photos)
}

/// Immediate subdirectories of `dir`, so the sidebar can offer them. Sorted by name.
pub fn subfolders(dir: &Path) -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return Vec::new();
    };
    let mut out: Vec<PathBuf> = entries
        .filter_map(|entry| {
            let path = entry.ok()?.path();
            path.is_dir().then_some(path)
        })
        .collect();
    out.sort_by(|a, b| folder_name(a).to_lowercase().cmp(&folder_name(b).to_lowercase()));
    out
}

/// The last path segment, for display.
pub fn folder_name(path: &Path) -> String {
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string())
}

/// Where the viewer looks first: the XDG pictures directory, falling back to `~/Pictures`.
pub fn default_root() -> PathBuf {
    if let Ok(dir) = std::env::var("SMART_IMAGE_VIEWER_DIR") {
        return PathBuf::from(dir);
    }

    // The XDG user-dirs file is the native answer on Linux, and it is what desktops and
    // file managers agree on.
    let Some(home) = home() else {
        return PathBuf::from(".");
    };
    let config = home.join(".config").join("user-dirs.dirs");
    let text = std::fs::read_to_string(&config).unwrap_or_default();
    pictures_dir_from(&text, &home)
}

/// Resolves `XDG_PICTURES_DIR` out of a `user-dirs.dirs` file.
///
/// Split out and pure so it can be tested without an environment: the original inline
/// version returned `/Pictures` on a real machine, because `Path::join` with an absolute
/// path throws the base away and `$HOME/Pictures` yields a `/Pictures` tail.
pub fn pictures_dir_from(config: &str, home: &Path) -> PathBuf {
    for line in config.lines() {
        let Some(rest) = line.strip_prefix("XDG_PICTURES_DIR=") else {
            continue;
        };
        let raw = rest.trim().trim_matches('"').trim();
        if raw.is_empty() {
            continue;
        }

        if let Some(tail) = raw.strip_prefix("$HOME") {
            // The leading slash must go: joining an absolute path would discard `home`.
            return home.join(tail.trim_start_matches('/'));
        }
        if raw.starts_with('/') {
            return PathBuf::from(raw);
        }
        return home.join(raw);
    }

    home.join("Pictures")
}

fn home() -> Option<PathBuf> {
    std::env::var_os("HOME")
        .map(PathBuf::from)
        .filter(|p| !p.as_os_str().is_empty())
}

